-- Port of Orders' InitialSchema migration. Invoice.CustomerId and
-- InvoiceLine.TrackId are plain indexed ids: customers belong to
-- Administration and tracks to Catalog, so no foreign key leaves this schema
-- (ADR-0004, ADR-0005).

CREATE TABLE orders."Invoice" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CustomerId" integer NULL,
    "InvoiceDate" timestamp with time zone NOT NULL,
    "BillingAddress" varchar(70) NULL,
    "BillingCity" varchar(40) NULL,
    "BillingState" varchar(40) NULL,
    "BillingCountry" varchar(40) NULL,
    "BillingPostalCode" varchar(10) NULL,
    "Total" numeric(10,2) NOT NULL,
    CONSTRAINT "PK_Invoice" PRIMARY KEY ("Id")
);

CREATE TABLE orders."InvoiceLine" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "InvoiceId" integer NULL,
    "TrackId" integer NULL,
    "UnitPrice" numeric(10,2) NULL,
    "Quantity" integer NULL,
    CONSTRAINT "PK_InvoiceLine" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_InvoiceLine_Invoice_InvoiceId" FOREIGN KEY ("InvoiceId") REFERENCES orders."Invoice" ("Id")
);

CREATE INDEX "IX_Invoice_CustomerId" ON orders."Invoice" ("CustomerId");
CREATE INDEX "IX_InvoiceLine_InvoiceId" ON orders."InvoiceLine" ("InvoiceId");
CREATE INDEX "IX_InvoiceLine_TrackId" ON orders."InvoiceLine" ("TrackId");
